def perim(r0,r1,c0,c1):
    p=[]
    for c in range(c0,c1+1): p.append((r0,c))
    for r in range(r0+1,r1+1): p.append((r,c1))
    for c in range(c1-1,c0-1,-1): p.append((r1,c))
    for r in range(r1-1,r0,-1): p.append((r,c0))
    return p
