def trace_hits(start,dr,dc,flip,stop_after=100):
    # move until hitting a wall (border), record the border cell, then reflect per flip mode; record every wall-hit cell; stop when re-entering start or too long
    hits=[]; seen=start; r,c=start; steps=0
    while steps<stop_after:
        r,c = r+dr, c+dc
        # clamp: wall crossing when next cell outside
        while not (r0<=r<=r1 and c0<=c<=c1):
            hit=(max(r0,min(r1,r)), max(c0,min(c1,c)))
            hits.append(hit)
            if r<r0 or r>r1:
                if flip in ('r','both'): dr=-dr
                r=max(r0,min(r1,r))
            if c<c0 or c>c1:
                if flip in ('c','both'): dc=-dc
                c=max(c0,min(c1,c))
            if hit==seen: return hits
        steps+=1
        if (r,c)==start: return hits
    return hits

